/**
 * The fifth review's corpus of good writing (copied from the reviewer's new-good1.ts to new-good5.ts, not changed in
 * substance): twenty-one good articles written without counting anything first, in shapes the earlier corpora did not
 * hold (a kit list, price lists in tables, a hospital-bag checklist, a jargon-buster, an FAQ page of one-word answers,
 * a legal explainer quoting statute, one-word topics). GOOD21 carries each article's d4e5527 score with and without a
 * picture; the tests hold every one to that score and to a pass of the gate (N6 apart: it was refused without a
 * picture at d4e5527 already, for its long quoted statute, and is held to exactly what it scored then).
 */
import type { ArticleBody } from '../src/seo-blog/types.js';
import type { Art } from './seo-score-review4-good.js';

const cite = (url: string, title: string) => ({ sourceId: title, url, title, retrievedAt: '2026-11-01T10:00:00.000Z', passage: title, public: true });
const img = (url: string, alt: string) => ({ kind: 'brand_asset', url, alt, provenance: '', width: 1536, height: 1024 });
const sec = (rows: [string, string][]) => rows.map(([heading, body], i) => ({ id: `s${i}`, heading, body }));

// N1 ── HOW-TO with numbered steps and short tips under each step
export const REGROUT: Art = { name: 'N1 how-to, numbered steps + short tips', site: 'https://www.tilewrightleeds.example',
  brief: { targetQuery: 'how to regrout bathroom tiles', searchIntent: 'learn', relatedQuestions: ['Can you put new grout over old grout?', 'How long does grout take to dry?', 'What tools do I need to regrout tiles?'] },
  body: { title: 'How to regrout bathroom tiles in a weekend', seoTitle: 'How to regrout bathroom tiles: a step-by-step guide',
    metaDescription: 'Learn how to regrout bathroom tiles yourself: the tools you need, how deep to rake out the old grout and how long to leave it before you shower.',
    excerpt: 'Fresh grout makes a tired bathroom look new. Here is how to do it properly.', slug: 'how-to-regrout-bathroom-tiles',
    intro: `Grey, cracked or mouldy grout makes a clean bathroom look dirty. The tiles themselves are usually fine, which is why learning how to regrout bathroom tiles is one of the best value jobs you can do in a house. A tiler would charge a day's labour. You can do it over a weekend for the price of a bag of grout and a rake.\n\nWe regrout a couple of bathrooms every week. These are the steps we follow, with the tips we give our own apprentices.`,
    sections: sec([
      ['What tools do I need to regrout tiles?', `Nothing here is expensive, and most of it will be in the shed already.\n\n- A grout rake with a carbide blade\n- A grout float\n- A bucket and a mixing stick\n- Two sponges\n- A soft cloth\n- Safety glasses and a dust mask\n\nBuy a spare blade for the rake. They blunt quickly on older, harder grout, and a blunt blade is how tiles get scratched.\n\nFor the grout itself, choose a ready-mixed tub for a splashback or a small area. For a whole shower wall, powder that you mix yourself is cheaper and stronger. Make sure the label says it is suitable for wet areas.`],
      ['Step by step', `Allow a morning for the raking out and an afternoon for the new grout.\n\n1. Rake out the old grout.\n2. Vacuum and wipe the joints.\n3. Mix the new grout.\n4. Work it into the joints.\n5. Wipe off the excess.\n6. Polish and leave to cure.\n\n### 1. Rake out the old grout\n\nRun the rake along each joint until you have removed at least two or three millimetres. Work the upright joints first, then the level ones. Keep the blade in the middle of the joint and let the tool do the work.\n\nTip: put an old towel in the bath or shower tray first. It catches the grit and saves the enamel.\n\n### 2. Vacuum and wipe the joints\n\nDust left in the joint stops new grout from gripping. Vacuum every line with the brush attachment, then wipe the wall with a damp sponge and let it dry for half an hour.\n\n### 3. Mix the new grout\n\nAdd powder to water, not water to powder, and stir until it looks like smooth peanut butter. Leave it to stand for three minutes and stir again.\n\nTip: mix less than you think you need. A batch starts to stiffen after about thirty minutes.\n\n### 4. Work it into the joints\n\nLoad the float and push the grout across the tiles at an angle, so it is pressed down into each joint and not just laid over the top. Cover about a square metre at a time.\n\n### 5. Wipe off the excess\n\nWait ten to fifteen minutes, until the surface has dulled. Then wipe diagonally across the tiles with a damp, well wrung sponge. Rinse it often. If the sponge is too wet you will pull the grout back out of the joints.\n\n### 6. Polish and leave to cure\n\nOnce a dry haze appears on the tiles, buff it away with a soft cloth. Then leave the wall alone.`],
      ['Can you put new grout over old grout?', `Only if you have raked the old grout out to a depth of two millimetres or more. A thin skim over the top of old grout has nothing to hold on to. It will look fine for a month and then flake away, usually in the corner where the shower hits it.\n\nIf the old grout is crumbling or black right through, take it out to the full depth of the tile. That is more work, but it is the only repair that lasts. Mould that has gone deep into the joint will come back through a thin new layer however much you bleach it first.`],
      ['How long does grout take to dry?', `Most cement grouts are dry to the touch in a few hours and can be wiped down the next morning. However, they need longer before they can take running water. Leave it 24 hours before a quick shower and three days before you seal it. Check the bag, because [the manufacturer's curing times](https://www.tilewrightleeds.example/guides/grout-curing-times) vary with the product and the temperature of the room.\n\nOpen a window while it cures. A cold, steamy bathroom can double the drying time.`],
    ]),
    conclusion: `Take your time over the raking out, because that is where the finish is decided. If you start the job and find loose tiles or a damp wall behind them, stop there and give us a ring before you go any further.`,
    cta: { label: 'Get a regrouting quote', url: 'https://www.tilewrightleeds.example/quote' },
    faqs: [
      { q: 'Should I seal new grout?', a: 'In a shower, yes. A clear grout sealer brushed on after three days keeps water and soap out of the joints and makes them far easier to clean.' },
      { q: 'What colour grout hides dirt best?', a: 'A mid grey. White shows every mark and very dark grout shows limescale, so a mid grey is the easiest to live with in a hard water area.' },
      { q: 'Can I regrout just one patch?', a: 'You can, but new grout rarely matches old grout of the same colour. It usually looks better to redo the whole wall while you have the tools out.' },
    ],
    citations: [cite('https://www.tiles.org.uk/advice/grouting', 'The Tile Association: grouting advice')],
    image: img('https://www.tilewrightleeds.example/images/regrout.jpg', 'A grout float pressing fresh grey grout between white bathroom tiles'), author: null } as unknown as ArticleBody };

// N2 ── SEASONAL ADVICE POST
export const WINTERGARDEN: Art = { name: 'N2 seasonal advice post', site: 'https://www.hollybankgardens.example',
  brief: { targetQuery: 'garden jobs for November', searchIntent: 'learn', relatedQuestions: ['What should I plant in November?', 'Should I cut the grass in November?', 'When should I lift dahlias?'] },
  body: { title: 'Garden jobs for November: what to do before the frost', seoTitle: 'Garden jobs for November: what to do before winter',
    metaDescription: 'Our garden jobs for November: what to plant, what to cut back and what to leave alone, from the team at Hollybank Gardens in the Peak District.',
    excerpt: 'The clocks have gone back, but there is still plenty to do outside.', slug: 'garden-jobs-for-november',
    intro: `November is the month when most people shut the back door and forget about the garden until March. That is a pity, because an hour or two now saves a great deal of work in spring. The soil is still warm from the summer, the ground is damp and the plants are going to sleep. That makes it the best planting month of the year for anything with roots.\n\nHere are the garden jobs for November that we do in our own nursery beds, roughly in the order we do them.`,
    sections: sec([
      ['What should I plant in November?', `Tulips come first. They should go in later than daffodils, and November is ideal because the colder soil protects them from a disease called tulip fire. Plant them three times as deep as the bulb is tall.\n\nThis is also the start of the bare-root season. Roses, hedging, fruit trees and raspberry canes are all sold without a pot from now until March. They cost about half as much as the same plant in a container, and they establish better. Soak the roots in a bucket for an hour before planting and firm them in well with your heel.\n\nIn the vegetable plot, sow broad beans and plant garlic. Both need a cold spell to do well, so do not wait for a mild day.`],
      ['Should I cut the grass in November?', `Yes, if it is still growing and the ground is not frozen or waterlogged. Grass keeps growing at anything above about five degrees, and in recent mild autumns we have been mowing into December.\n\nRaise the blades to their highest setting, though. Longer grass copes better with frost and shades out moss. Never mow when there is frost on the lawn, because the blades of grass snap and you will see your footprints in brown for weeks.\n\nRake up fallen leaves at least once a week. A thick layer left on the lawn blocks the light and leaves yellow patches. Bag them up in old compost sacks with a few holes punched in the sides, and in a year you will have leaf mould for nothing.`],
      ['When should I lift dahlias?', `Wait for the first hard frost to blacken the leaves. That tells the plant to draw its energy back down into the tuber. Then cut the stems to about a hand's width above the ground and lift the whole clump with a fork.\n\nShake off the soil and stand the tubers upside down for a few days so that water drains from the hollow stems. Store them somewhere dry and frost free, such as a garage, in trays of dry compost or sand.\n\nIf your soil is light and you live in a mild area, you can leave them in the ground instead. Cover them with a thick mulch of bark or straw. On heavy clay, like ours, they nearly always rot, so we lift every one.`],
      ['What to leave alone', `Tidying can go too far. Leave the seed heads on teasels, sedums and grasses, because the birds will feed on them all winter and they look lovely with frost on them. Hollow stems are also where ladybirds and lacewings spend the cold months.\n\nDo not prune plums, cherries or other stone fruit now. Cuts made in winter let in silver leaf disease, so those trees wait until summer. Hold back on the hedge trimmer too if the hedge has berries on it.\n\nFinally, check any bonfire heap before you light it. Hedgehogs think a pile of dry leaves and twigs is the perfect bed. The [RSPB's advice on winter wildlife](https://www.hollybankgardens.example/wildlife/winter) is to move the whole pile on the day you burn it.`],
    ]),
    conclusion: `None of this needs doing in one weekend. Pick a dry afternoon, plant the tulips first and work down the list from there. Our nursery is open every day until Christmas Eve if you need bulbs, bare-root roses or just some advice.`,
    cta: { label: 'See our bare-root plants', url: 'https://www.hollybankgardens.example/bare-root' },
    faqs: [
      { q: 'Is it too late to plant daffodils?', a: 'No. They prefer September, but daffodil bulbs planted in November will still flower. They may be a little shorter and a week or two later in their first year.' },
      { q: 'Should I feed the lawn now?', a: 'Only with an autumn feed, which is low in nitrogen. A spring or summer feed makes soft growth that the first frost will damage.' },
      { q: 'Do I need to water new plants in winter?', a: 'Usually not, because the rain does it for you. Check anything planted under the eaves of the house or in a pot, since those can stay dry all winter.' },
    ],
    citations: [cite('https://www.rhs.org.uk/advice/in-month/november', 'RHS: gardening in November')],
    image: img('https://www.hollybankgardens.example/images/november-border.jpg', 'A gardener planting tulip bulbs in a frosty border on a November morning'), author: null } as unknown as ArticleBody };

// N3 ── "X vs Y" WITH A TABLE
export const SOLEVLTD: Art = { name: 'N3 "X vs Y" with a table', site: 'https://www.marlowledger.example',
  brief: { targetQuery: 'sole trader vs limited company', searchIntent: 'compare', relatedQuestions: ['Is it better to be a sole trader or a limited company?', 'Do you pay less tax as a limited company?', 'Can I change from sole trader to limited company?'] },
  body: { title: 'Sole trader vs limited company: which is right for you?', seoTitle: 'Sole trader vs limited company: the differences that matter',
    metaDescription: 'Sole trader vs limited company compared side by side: tax, paperwork, risk and cost, with a plain rule of thumb for when it is worth making the switch.',
    excerpt: 'Two ways to run the same business, and what each one costs you.', slug: 'sole-trader-vs-limited-company',
    intro: `Almost every new client asks us the same thing in their first meeting: sole trader vs limited company, which should I be? There is no single right answer. It depends on how much profit you make, how much risk the work carries and how much paperwork you can stand.\n\nThis guide sets the two side by side. It is written for people running small businesses in England and Wales, and the figures are for the 2026 to 2027 tax year.`,
    sections: sec([
      ['The two structures in one table', `If you only have a minute, this is the short version. The rest of the article explains each row.\n\n| | Sole trader | Limited company |\n|---|---|---|\n| Set-up | Register with HMRC, free | Register at Companies House, £50 |\n| Who owns the profit | You do | The company does |\n| Tax on profit | Income tax and National Insurance | Corporation tax, then tax on what you take out |\n| If things go wrong | You are personally liable | Your liability is limited |\n| Accounts | Self assessment return | Company accounts, company tax return and your own return |\n| Privacy | Nothing published | Accounts and directors are public |\n| Typical accountancy cost | £300 to £600 a year | £1,000 to £2,000 a year |\n\nNeither column is better. They suit different stages of a business.`],
      ['Is it better to be a sole trader or a limited company?', `For most people starting out, a sole trader is the better choice. You can register in ten minutes, you keep simple records and you send one tax return a year. If the business does not work out, you just stop.\n\nA limited company starts to make sense in three situations. The first is when your profit is high enough for the tax saving to cover the extra cost. The second is when the work is risky, because the company, not you, owes its debts. The third is when customers expect it. Some larger firms and public bodies will only give contracts to limited companies.\n\nAs a rough rule, we suggest clients look at it again once profits pass about £50,000 a year. Below that, the saving rarely pays for the extra accountancy.`],
      ['Do you pay less tax as a limited company?', `Often, but not always, and by less than people expect. A sole trader pays income tax and National Insurance on all the profit of the business, whether or not they spend it. A company pays corporation tax on its profit first. You then pay tax yourself on what you take out as salary and dividends.\n\nThe saving comes from two things. Dividends are taxed at lower rates than wages, and they carry no National Insurance. In addition, you can leave money in the company in a good year and take it out in a lean one.\n\nHowever, the gap has narrowed. Corporation tax for profits over £50,000 has risen, and the tax-free dividend allowance is now only £500. On a profit of £30,000 the difference is a few hundred pounds, which the higher accountancy bill will swallow. On £80,000 it can be several thousand. HMRC publishes the [current rates and allowances](https://www.gov.uk/government/publications/rates-and-allowances-corporation-tax) each year, and we run the sum for every client before they decide.`],
      ['Risk, paperwork and privacy', `Limited liability is the reason the limited company exists. If the company cannot pay its debts, your house and savings are normally safe. For a sole trader there is no line between business and personal money, so a large claim or an unpaid supplier is your own debt.\n\nThat protection has limits. Banks and landlords usually ask a director of a small company for a personal guarantee. Directors can also be held responsible if they keep trading when they know the company cannot pay.\n\nThe price is paperwork. A company must file accounts and a confirmation statement at Companies House every year, as well as a corporation tax return. You become an employee of your own company, so there is a payroll to run. Late filing brings automatic penalties. Your accounts, your name and a service address also go on the public register, where anyone can read them.`],
      ['Can I change from sole trader to limited company?', `Yes, at any time, and plenty of businesses do exactly that after a few years. You form the company, move the trade across and tell HMRC that your self-employment has ended. Customers, suppliers and the bank all need to know, because contracts and accounts are in the name of the business owner.\n\nThe timing matters. Changing at the end of your accounting year keeps the tax simple. If you own equipment, a van or stock, those are sold or transferred to the company, and that can have tax effects of its own. We set out [how incorporation works, step by step](https://www.marlowledger.example/guides/incorporating-your-business), and we would always suggest taking advice before you do it.\n\nGoing the other way is harder. Closing a company takes months and costs money, so do not incorporate just to try it.`],
    ]),
    conclusion: `Start simple unless there is a clear reason not to. Stay a sole trader while profits are modest and risks are low, and move to a company when the numbers or your customers say it is time. If you would like the calculation done on your own figures, that is what our first meeting is for.`,
    cta: { label: 'Book a free first meeting', url: 'https://www.marlowledger.example/contact' },
    faqs: [
      { q: 'Does a limited company need an accountant?', a: 'Not by law, but nearly every company uses one. Company accounts must follow a set format, and mistakes bring penalties.' },
      { q: 'Can a sole trader employ staff?', a: 'Yes. A sole trader can take on employees and run a payroll in exactly the same way as a company.' },
      { q: 'Will I have to register for VAT?', a: 'Only once your turnover passes the VAT threshold. That rule is the same for sole traders and companies.' },
    ],
    citations: [cite('https://www.gov.uk/set-up-business', 'GOV.UK: set up a business')],
    image: img('https://www.marlowledger.example/images/structures.jpg', 'An accountant comparing sole trader and limited company figures on two sheets of paper'), author: null } as unknown as ArticleBody };

// N4 ── CASE-STUDY STYLE POST (a typical job, told plainly; no invented statistics)
export const DAMP: Art = { name: 'N4 case-study style post', site: 'https://www.kelhamdamp.example',
  brief: { targetQuery: 'rising damp treatment', searchIntent: 'learn', relatedQuestions: ['How do you treat rising damp?', 'How much does rising damp treatment cost?', 'How do I know if I have rising damp?'] },
  body: { title: 'Rising damp treatment: how we dried out a Victorian terrace', seoTitle: 'Rising damp treatment in a Victorian terrace: a real job',
    metaDescription: 'A real rising damp treatment job from start to finish: how we found the cause in a Sheffield terrace, what we did about it and what the owners paid.',
    excerpt: 'One house, one damp wall and what it took to put it right.', slug: 'rising-damp-treatment-victorian-terrace',
    intro: `People ring us about rising damp treatment when they have already been frightened by a quote. So this post walks through one ordinary job, with the owners' permission, to show what actually happens and why.\n\nThe house is a two-bedroom brick terrace in Walkley, built around 1890. The owners had bought it a year earlier. By their first winter, the paint on the front room wall was bubbling and there was a tide mark about knee high.`,
    sections: sec([
      ['How do I know if I have rising damp?', `That was their first question, and it is the right one. Most damp in old houses is not rising damp at all. It is condensation, a leaking gutter or soil piled against the wall outside.\n\nRising damp has a particular look. The damage starts at the floor and stops at about a metre. There is often a wavy line of white, fluffy salts along the top edge. The skirting boards may be soft, and the plaster sounds hollow when you knock on it.\n\nWe checked three things on the first visit. We took readings up the wall with a moisture meter, and they fell away steadily with height. We looked outside and found the pavement had been raised, so it now sat above the old slate damp-proof course. Finally, we lifted a floorboard and found the air bricks blocked with rubble. Any one of those can cause the problem. This house had all three.`],
      ['How do you treat rising damp?', `You deal with the cause first and the wall second. There is no point injecting a wall that is being soaked by a leaking downpipe.\n\nOn this job the work went in four stages.\n\n1. Clear the air bricks and the space under the floor.\n2. Hack off the damaged plaster to just over a metre.\n3. Inject a new damp-proof course.\n4. Replaster with a salt-resistant render.\n\nClearing the air bricks took a morning and made more difference than anything else. Timber floors need a draught under them, and this one had been sitting in still, wet air for years.\n\nFor the new damp-proof course we drilled into the mortar line, six inches above the outside ground, and injected a silicone cream. The cream spreads through the mortar and lines the pores so that water can no longer climb. It is a standard method, covered by [British Standard 6576](https://www.kelhamdamp.example/guides/bs-6576-explained), and it is the one most surveyors expect to see.\n\nThe replastering matters just as much. Old plaster is full of salts that pull moisture out of the air, so a wall can stay damp to the touch even after the water has stopped rising. We used a sand and cement render with a salt inhibitor, then a skim coat.`],
      ['How much does rising damp treatment cost?', `This job came to £1,850 plus VAT for one front room wall, about four and a half metres long. That covered the survey, the injection, the replastering and a new length of skirting board.\n\nPrices for a terrace like this one usually fall between £1,200 and £3,000 for a single wall. The injection itself is the cheap part. Most of the bill is plastering, because that is where the hours go. If the floor joists have rotted where they meet the wall, that is extra, and nobody can tell you until the boards are up.\n\nBe wary of a quote given over the phone, or one that prices every wall in the house without a single meter reading. A proper survey should name the cause, not just the cure.`],
      ['What happened next', `The wall took about four months to dry fully. A solid brick wall loses roughly an inch of moisture a month, so we tell every customer the same thing: do not paint it with ordinary emulsion until it has dried. The owners used a breathable mist coat in the meantime.\n\nWe went back after the following winter. The readings were normal from floor to ceiling, and the new skirting was dry behind. The owners had also asked the council about the raised pavement. That is still being discussed, which is why the new damp-proof course sits above it.`],
    ]),
    conclusion: `Every damp wall has a cause, and the treatment only works when the cause is found first. If you have a tide mark and a quote you are not sure about, we are happy to give a second opinion on it.`,
    cta: { label: 'Book a damp survey', url: 'https://www.kelhamdamp.example/survey' },
    faqs: [
      { q: 'Does the treatment come with a guarantee?', a: 'Ours carries a 20-year guarantee that passes to the next owner when the house is sold, backed by insurance.' },
      { q: 'Can I stay in the house during the work?', a: 'Yes. The room being treated is out of use for about a week, and the hacking off is dusty, but there is no need to move out.' },
      { q: 'Will rising damp come back?', a: 'Not if the cause has been dealt with. It returns when the ground outside is raised again or the air bricks are blocked.' },
    ],
    citations: [cite('https://www.property-care.org/homeowners/advice/rising-damp', 'Property Care Association: rising damp')],
    image: img('https://www.kelhamdamp.example/images/terrace-wall.jpg', 'A bare brick wall after rising damp treatment, with plaster removed to a metre high'), author: null } as unknown as ArticleBody };

