// P4 ── "IDEAS" LISTICLE: thirty one-line ideas in groups
export const RAINYDAY: Art = { name: 'P4 ideas listicle, one line each', site: 'https://www.littleacornsnursery.example',
  brief: { targetQuery: 'rainy day activities for toddlers', searchIntent: 'learn', relatedQuestions: ['What can I do with a toddler on a rainy day?', 'How do you entertain a 2 year old indoors?'] },
  body: { title: '30 rainy day activities for toddlers', seoTitle: '30 rainy day activities for toddlers that need no screens',
    metaDescription: 'Thirty rainy day activities for toddlers from our nursery staff, using things you already have at home. No screens, no craft shop and very little mess.',
    excerpt: 'Thirty ideas from our nursery staff, using what is already in the house.', slug: 'rainy-day-activities-for-toddlers',
    intro: `It has rained for three days, the park is a bog and it is only ten past nine. We know the feeling, because we look after forty under-fives through every wet week of a Lancashire winter.\n\nThese are the rainy day activities for toddlers that our staff fall back on. None needs a trip to the shops.`,
    sections: sec([
      ['What can I do with a toddler on a rainy day?', `Start with something that uses the whole body. A toddler who has climbed, jumped and carried things for half an hour will then sit down happily.\n\n- Build a den from the clothes airer and a sheet\n- Lay cushions across the floor as stepping stones\n- Roll socks into balls and throw them into the washing basket\n- Put on music and freeze like statues when it stops\n- Make an obstacle course with chairs to crawl under\n- Blow bubbles in the kitchen and stamp on them\n- Push teddies round the house in a cardboard box\n- Tape a line on the floor and walk it like a tightrope\n- Have a teddy bears' picnic on a blanket indoors\n- Put wellies on and go out anyway for ten minutes`],
      ['Messy play without much mess', `Put an old shower curtain or a bath towel down first, and most of this wipes up in a minute.\n\n- Fill the washing-up bowl with water, cups and a sieve\n- Paint the patio doors with a brush and plain water\n- Make play dough from flour, salt, oil and water\n- Hide toy animals in a tray of dry rice or oats\n- Draw round hands and feet on the back of wallpaper\n- Stick dry pasta on to paper with a glue stick\n- Wash the toy cars in a bowl of bubbles\n- Print with halved potatoes and a saucer of paint\n- Thread large pasta tubes on to a shoelace\n- Give the dolls a bath in the sink`],
      ['How do you entertain a 2 year old indoors?', `Give them real jobs. At two, children want to do what you are doing far more than they want a toy. It takes longer, but it fills the morning and they are proud of themselves.\n\n- Match the socks from the clean washing\n- Wipe the table with a damp cloth\n- Water the house plants with a small jug\n- Wash vegetables for tea in a colander\n- Stir cake mix and spoon it into cases\n- Sort the cutlery into the drawer\n- Feed the washing machine and press the button\n- Post letters through a slot cut in a box\n- Sweep the floor with a dustpan and brush\n- Tear up lettuce for a sandwich\n\nKeep each one short. Ten minutes is a long time when you are two, and a change of room often works as well as a change of game. The NHS guide to [keeping under-fives active](https://www.littleacornsnursery.example/parents/active-play) suggests three hours of movement spread over the day.`],
    ]),
    conclusion: `You will not need all thirty. Pick one from each list, and by the time you have cleared up it will be lunch. If the rain goes on all week, our stay and play sessions run on Tuesday and Thursday mornings, and you are very welcome.`,
    cta: { label: 'Book a stay and play session', url: 'https://www.littleacornsnursery.example/stay-and-play' },
    faqs: [
      { q: 'How long should an activity last?', a: 'For a two year old, five to fifteen minutes is normal. Moving on quickly is a sign of their age, not of a bad idea.' },
      { q: 'Is it all right to go out in the rain?', a: 'Yes. With waterproofs and wellies a short, wet walk is good for everyone, and puddles are an activity in themselves.' },
      { q: 'What if I have no craft supplies?', a: 'You do not need any. Water, cardboard boxes, cushions and the clean washing cover most of the ideas on this page.' },
    ],
    citations: [cite('https://www.nhs.uk/live-well/exercise/physical-activity-guidelines-children-under-five-years/', 'NHS: physical activity guidelines for children under five')],
    image: img('https://www.littleacornsnursery.example/images/den.jpg', 'A toddler peeping out of a den made from a sheet on a rainy day'), author: null } as unknown as ArticleBody };

